// Get all items from the input
const items = $input.all();

if (!items || items.length === 0) {
  return [];
}

// Emoji definitions using Unicode escapes
const EMOJI = {
  seedling: '\u{1F331}',    // 🌱
  fire: '\u{1F525}',        // 🔥
  star: '\u{2B50}',         // ⭐
  herb: '\u{1F33F}',        // 🌿
  leaf: '\u{1F343}',        // 🍃 (for low priority)
  warning: '\u{26A0}\u{FE0F}', // ⚠️
  calendar: '\u{1F4C5}',    // 📅
  clipboard: '\u{1F4CB}',   // 📋
  plant: '\u{1FAB4}',       // 🪴
  tada: '\u{1F389}'         // 🎉
};

// Group tasks by telegram_id
const grouped = {};

for (const item of items) {
  const chatId = item.json.telegram_id;
  const fullName = item.json.full_name || 'there';

  if (!chatId) continue;

  if (!grouped[chatId]) {
    grouped[chatId] = {
      chat_id: chatId,
      first_name: fullName.split(' ')[0],
      dueTasks: [],
      noDeadlineTasks: []
    };
  }

  const task = {
    description: item.json.description,
    deadline: item.json.deadline,
    priority: item.json.priority || 'Medium',
    status: item.json.status
  };

  if (item.json.deadline === null || item.json.deadline_type === 'no_deadline') {
    grouped[chatId].noDeadlineTasks.push(task);
  } else {
    grouped[chatId].dueTasks.push(task);
  }
}

// Format messages for each user
const output = [];

for (const chatId in grouped) {
  const user = grouped[chatId];
  const dueCount = user.dueTasks.length;
  const backlogCount = user.noDeadlineTasks.length;

  if (dueCount === 0 && backlogCount === 0) continue;

  let message = EMOJI.seedling + ' *Good morning ' + user.first_name + '!*\n\n';

  if (dueCount > 0) {
    message += 'You have *' + dueCount + ' seed' + (dueCount > 1 ? 's' : '') + '* to water today:\n\n';

    const priorityOrder = { 'High': 0, 'high': 0, 'Medium': 1, 'medium': 1, 'Low': 2, 'low': 2 };
    user.dueTasks.sort((a, b) => {
      const priorityDiff = (priorityOrder[a.priority] ?? 2) - (priorityOrder[b.priority] ?? 2);
      if (priorityDiff !== 0) return priorityDiff;
      return new Date(a.deadline) - new Date(b.deadline);
    });

    user.dueTasks.forEach((task, index) => {
      const deadline = new Date(task.deadline);
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      deadline.setHours(0, 0, 0, 0);

      const diffDays = Math.floor((deadline - today) / (1000 * 60 * 60 * 24));
      let deadlineText = '';

      if (diffDays < 0) {
        deadlineText = EMOJI.warning + ' Overdue by ' + Math.abs(diffDays) + ' day' + (Math.abs(diffDays) > 1 ? 's' : '');
      } else if (diffDays === 0) {
        deadlineText = EMOJI.calendar + ' Due today';
      } else {
        deadlineText = EMOJI.calendar + ' Due in ' + diffDays + ' day' + (diffDays > 1 ? 's' : '');
      }

       let priorityEmoji = EMOJI.leaf;  // Default to low
      if (task.priority === 'High' || task.priority === 'high') {
        priorityEmoji = EMOJI.fire;
      } else if (task.priority === 'Medium' || task.priority === 'medium') {
        priorityEmoji = EMOJI.star;
      }

      let statusEmoji = '';
      const statusLower = (task.status || '').toLowerCase();
      if (statusLower === 'in progress' || statusLower === 'in_progress') {
        statusEmoji = ' ' + EMOJI.herb;
      }

      message += (index + 1) + '. ' + priorityEmoji + ' ' + task.description + statusEmoji + '\n';
      message += '   ' + deadlineText + '\n\n';
    });
  } else {
    message += 'No urgent tasks due today! ' + EMOJI.tada + '\n\n';
  }

  if (backlogCount > 0) {
    message += EMOJI.clipboard + ' *Backlog:* ' + backlogCount + ' task' + (backlogCount > 1 ? 's' : '') + ' without deadline' + (backlogCount > 1 ? 's' : '') + '\n';
    message += '   → Check your GrowFlow dashboard to prioritize\n\n';
  }

  message += EMOJI.plant + ' _Water your tasks, watch your garden grow!_';

  output.push({
    json: {
      chat_id: user.chat_id,
      first_name: user.first_name,
      task_count: dueCount,
      backlog_count: backlogCount,
      message_text: message
    }
  });
}

return output;

// Parse the JSON string from Vision output
const parsed = JSON.parse($input.first().json['0'].content[0].text);
const data = parsed.extracted_data;

// Calculate end time if not provided
const calculateEndTime = (startTime) => {
  if (!startTime) return "22:00";
  const [hours, minutes] = startTime.split(':');
  const endHour = (parseInt(hours) + 3) % 24;
  return `${String(endHour).padStart(2, '0')}:${minutes}`;
};

const eventData = {
  summary: data.event_title || 'Untitled Event',
  start_datetime: `${data.event_date}T${data.event_time}:00+05:30`,
  end_datetime: `${data.event_date}T${data.event_end_time || calculateEndTime(data.event_time)}:00+05:30`,
  location: data.venue || '',
  description: `${data.notes || ''}\n\nHosts: ${data.hosts ? data.hosts.join(', ') : 'Unknown'}\n\nRSVP: ${data.rsvp_info || 'N/A'}\n\n---\nAdded via GrowFlow from Telegram`,
  color: '5',
  original_data: data
};

return { json: eventData };

