const eventData = $('calendar_events insert').item.json;

const escape = (text) => {
  return text.replace(/[_*[\]()~`>#+\-=|{}.!]/g, '\\$&');
};

const startDateTime = new Date(eventData.event_date + 'T' + eventData.event_time);
const endDateTime = new Date(eventData.event_date + 'T' + eventData.event_end_time);

const dateOptions = { year: 'numeric', month: 'long', day: 'numeric' };
const formattedDate = startDateTime.toLocaleDateString('en-US', dateOptions);

const timeOptions = { hour: 'numeric', minute: '2-digit', hour12: true };
const startTime = startDateTime.toLocaleTimeString('en-US', timeOptions);
const endTime = endDateTime.toLocaleTimeString('en-US', timeOptions);

const message = `✅ *Calendar event created successfully\\!*

📅 *${escape(eventData.event_title)}*

📍 *Location:* ${escape(eventData.venue || 'Not specified')}

🗓️ *Date:* ${escape(formattedDate)}

🕐 *Time:* ${escape(startTime)} \\- ${escape(endTime)}

🔗 [View in Google Calendar]($('Create an event').first().json.htmlLink)

🌱 *Reminder task added to your GrowFlow dashboard*

💡 *You'll receive reminders before the event\\.*

🌱 _Powered by GrowFlow_`;

return {
  json: {
    message: message,
    chat_id: eventData.telegram_id
  }
};

const eventData = $('Prepare Event Data').item.json;
const calendarEvent = $('Create an event').item.json; // Get from Google Calendar node
const telegramData = $('Telegram Trigger').item.json;

const extractTime = (datetime) => datetime.split('T')[1].split('+')[0].substring(0, 5);

return {
  json: {
    telegram_id: String(telegramData.message.from.id),
    event_title: eventData.summary,
    event_date: eventData.start_datetime.split('T')[0],
    event_time: extractTime(eventData.start_datetime),
    event_end_time: extractTime(eventData.end_datetime),
    venue: eventData.location,
    hosts: eventData.original_data.hosts || [],
    rsvp_info: eventData.original_data.rsvp_info,
    event_type: eventData.original_data.event_type,
    notes: eventData.original_data.notes,
    google_calendar_event_id: calendarEvent.id,
    google_calendar_link: calendarEvent.htmlLink,
    source: 'telegram_image'
  }
};
